param()
$ErrorActionPreference='Stop'
Set-StrictMode -Version 2
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=(Resolve-Path '.').Path
$out=Join-Path $root 'output/a_ttq_asset_audit_20260925_01'
$visited=[ordered]@{}
function Abs([string]$p){if($p.StartsWith('/mnt/e/')){return ('E:\'+$p.Substring(7).Replace('/','\'))};if([IO.Path]::IsPathRooted($p)){return $p};return Join-Path $root $p}
function Sha([string]$p){$p=Abs $p;$h=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant();$visited[$p]=$h;return $h}
function J([string]$p){return (Get-Content -LiteralPath (Abs $p) -Raw -Encoding UTF8 | ConvertFrom-Json)}
function Must($ok,[string]$msg){if(-not $ok){throw $msg}}
function Npz([string]$path){
 $z=[IO.Compression.ZipFile]::OpenRead((Abs $path));$result=[ordered]@{}
 try {foreach($e in $z.Entries){$s=$e.Open();$m=New-Object IO.MemoryStream;try{$s.CopyTo($m);$b=$m.ToArray()}finally{$s.Dispose();$m.Dispose()};Must ($b[0]-eq147 -and [Text.Encoding]::ASCII.GetString($b,1,5)-eq'NUMPY') 'NPY magic';$off=if($b[6]-eq1){10}else{12};$len=if($off-eq10){[BitConverter]::ToUInt16($b,8)}else{[BitConverter]::ToUInt32($b,8)};$head=[Text.Encoding]::ASCII.GetString($b,$off,$len);$sh=[Security.Cryptography.SHA256]::Create();try{$hash=([BitConverter]::ToString($sh.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$sh.Dispose()};$result[$e.FullName]=[ordered]@{npy_header=$head.Trim();npy_bytes=$b.Length;npy_sha256=$hash}}}finally{$z.Dispose()};return $result
}
$balanced='output/a_balanced_20260925_01';$longfit='output/a_longfit_20260925_01';$warm='output/a_warm_start_20260925_01';$control='output/a_warm_start_controls_20260925_01';$single='output/a_margin_single_20260925_01'
$bp=J "$balanced/RUN_PROTOCOL.json";$wp=J "$warm/RUN_PROTOCOL.json";$cp=J "$control/RUN_PROTOCOL.json";$sp=J "$single/RUN_PROTOCOL.json";$bm=J "$balanced/DATA_MANIFEST.json";$lm=J "$longfit/DATA_MANIFEST.json"
$semPath='output/a_reference_semantics_20260925_01/RESULTS.json';$sem=J $semPath;$semSha=Sha $semPath;Must ($semSha-eq'8f474af459b9e52337fdbb239e63802cae368012aace5207e199dce4737917ee') 'Semantics evidence changed'
Must ($bp.uids.Count-eq16 -and ($bp.uids|Select-Object -Unique).Count-eq16) '16 unique parents'
$data=@();$first=$null
foreach($uid in $bp.uids){$rel="data/$uid.npz";$path="$balanced/$rel";$hash=Sha $path;Must ($hash-eq$bm.files.$rel -and $hash-eq$lm.files.$rel) 'Data manifests disagree';$npz=Npz $path;$sr=@($sem.rows|Where-Object {$_.uid-eq$uid});Must ($sr.Count-eq1 -and $sr[0].source_archive_sha256-eq$hash -and $sr[0].vertices_bitwise_equal -and $sr[0].faces_bitwise_equal) 'Reference evidence mismatch';if($null-eq$first){$first=$npz};foreach($key in @('faces.npy','base_u.npy','ref_faces.npy')){Must ($npz[$key].npy_sha256-eq$first[$key].npy_sha256) 'Shared template differs'};Must ($npz['faces.npy'].npy_header -match "'shape': \(512, 3\)" -and $npz['base_u.npy'].npy_header -match "'shape': \(258, 3\)") 'Template shape';$data+=,[ordered]@{uid=$uid;split=if($bp.train_uids-contains$uid){'train'}else{'internal_check_seen'};path=(Abs $path);wsl_path=('/mnt/e/'+(Abs $path).Substring(3).Replace('\','/'));file_sha256=$hash;metadata=$npz;mainfield_hash=$sr[0].logr_hash;reference_hash=$sr[0].reference_hash;same_field_reference_verified_by_bound_prior_exact_array_check=$true;new_reference_reconstruction_performed=$false}}
$models=[ordered]@{}
foreach($name in @('early_v1_10','balanced_10','balanced_11')){$bind=if($name-eq'early_v1_10'){$cp.model_bindings.$name}else{$wp.model_bindings.$name};$actual=Sha $bind.path;Must ($actual-eq$bind.file_sha256) 'Model checkpoint differs';if($name-eq'early_v1_10'){Must ($actual-eq$sp.hashes.initial_checkpoint_sha256 -and $bind.model_sha256-eq$sp.hashes.initial_model_sha256 -and $bind.source_stored_update-eq3000) 'Early 3k binding'}else{Must ((Sha $bind.protocol_path)-eq$bind.protocol_sha256 -and (Sha $bind.training_report_path)-eq$bind.training_report_sha256) 'Balanced report binding';$tr=J $bind.training_report_path;Must ($tr.update-eq240000 -and $tr.model_sha256-eq$bind.model_sha256) 'Balanced final update/model'};$models[$name]=[ordered]@{binding=$bind;actual_checkpoint_file_sha256=$actual;file_binding_pass=$true;tensor_hash_from_bound_prior_evidence=$bind.model_sha256;new_tensor_hash_recomputed=$false;no_forward_performed=$true}}
$kinds=@('raw','snapshot_0','snapshot_1','snapshot_4','snapshot_16','optimizer_final');$hist=@()
foreach($uid in $wp.uids){foreach($model in @('fixed','early_v1_10','balanced_10')){$run=if($model-eq'early_v1_10'){$control}else{$warm};$base="$run/attempts/$uid/$model";$task=J "$base/TASK.json";$opt=J "$base/OPTIMIZER.json";$tasksha=Sha "$base/TASK.json";$optsha=Sha "$base/OPTIMIZER.json";$arr=Npz "$base/OPTIMIZER_ARRAYS.npz";$arrsha=Sha "$base/OPTIMIZER_ARRAYS.npz";Must ($arrsha-eq$opt.arrays_sha256) 'Optimizer arrays hash';$obs=@();foreach($kind in $kinds){$rowpath="$base/$kind/RESULT.json";$row=J $rowpath;$mesh=(Abs "$run/$($row.mesh_file)");Must ((Sha $mesh)-eq$row.mesh_npz_sha256) 'Warm mesh file mismatch';Must ($row.metrics.Count-eq2 -and $row.metrics[0].points_per_direction-eq8192 -and $row.metrics[1].points_per_direction-eq8192) 'MC pair missing';$idx=[Array]::IndexOf(@($bp.uids),$uid);Must ($row.metrics[0].seed-eq1593501+$idx -and $row.metrics[1].seed-eq1693501+$idx) 'Warm MC seed differs';$obs+=,[ordered]@{kind=$kind;status=$row.status;row_path=(Abs $rowpath);row_sha256=(Sha $rowpath);mesh_file=$mesh;mesh_npz_sha256=$row.mesh_npz_sha256;mesh_hash=$row.mesh_hash;mainfield_hash=$row.mainfield_hash;reference_hash=$row.GT_reference_hash;qualified=$row.qualified;metrics=$row.metrics;actual_iteration=if($row.PSObject.Properties.Name-contains'actual_iteration'){$row.actual_iteration}else{$null};stored_independent_MC_reusable_if_same_mesh_reference_seeds_and_estimator=$true}};$iters=@($opt.trace|ForEach-Object {$_.iteration});$full=($iters.Count-eq17 -and (($iters -join ',')-eq((0..16)-join ',')));$hist+=,[ordered]@{uid=$uid;model=$model;task_path=(Abs "$base/TASK.json");task_sha256=$tasksha;optimizer_path=(Abs "$base/OPTIMIZER.json");optimizer_sha256=$optsha;status=$task.status;stats=$opt.stats;trace_iterations=$iters;every_iteration_trace_0_to16_present=$full;trace_has_internal_loss_quality_elapsed=$true;saved_geometry_snapshot_iterations=@($opt.snapshots|ForEach-Object {$_.iteration});dense_all_iteration_meshes_and_independent_MC_present=$false;optimizer_arrays_metadata=$arr;optimizer_arrays_sha256=$arrsha;recorded_timing=[ordered]@{raw_initialization=$task.raw_initialization;floor_setup_seconds=$task.fixed_floor_generation_and_check_seconds;optimizer_call_wall_seconds=$task.optimizer_call_wall_seconds;initialization_plus_optimizer_seconds=$task.initialization_plus_optimizer_seconds;initialization_floor_optimizer_finalcheck_seconds=$task.initialization_floor_optimizer_finalcheck_seconds;old_measurement_not_isolated_reusable_as_historical_only=$true};observations=$obs}}}
$catalog=@()
$defs=@(@('a_taskaligned_20260924_01','student_10'),@('a_endpoint_20260924_01','v1_10'),@('a_fitdiag_20260925_01',''),@('a_longfit_20260925_01',''),@('a_balanced_20260925_01','joint_10'))
foreach($def in $defs){$rp="output/$($def[0])/results.json";$ledger=J $rp;$rs=Sha $rp;$wanted=@('fixed');if($def[1]){$wanted+=$def[1]};foreach($name in $wanted){$rows=@($ledger.rows|Where-Object {$_.model-eq$name -and $_.policy-eq'raw'});$bindings=@();foreach($row in $rows){$path="output/$($def[0])/$($row.mesh_file)";Must ((Sha $path)-eq$row.mesh_npz_sha256) 'Existing baseline mesh changed';$bindings+=,[ordered]@{uid=$row.uid;mesh_path=(Abs $path);mesh_npz_sha256=$row.mesh_npz_sha256;mainfield_hash=$row.mainfield_hash;metrics=$row.metrics;qualified=$row.qualified}};$catalog+=,[ordered]@{run=$def[0];ledger_path=(Abs $rp);ledger_sha256=$rs;model=$name;raw_rows=$rows.Count;metrics_seed_base_pairs=@($rows|Select-Object -First 1|ForEach-Object {,$_.metrics.seed});rows=$bindings;reuse_scope='same UID/mainfield, same stored mesh, identical MC seeds/count/estimator only; differing seeds cannot form a paired ratio'}}}
$bl=J "$balanced/results.json";$b11rows=@($bl.rows|Where-Object {$_.model-eq'joint_11' -and $_.policy-eq'raw'});$b11errors=@($bl.errors|Where-Object {$_.model-eq'joint_11'})
$sources=[ordered]@{};foreach($rel in @('experiments/a_radial/AGENTS.md','experiments/a_radial/system_probe/warm_start.py','experiments/a_radial/system_probe/warm_start_controls.py','experiments/a_radial/layout_value/optimizer.py','experiments/a_radial/layout_student/deployment.py','experiments/a_radial/legacy/deform.py','experiments/a_radial/legacy/chart.py','experiments/a_radial/assets/support.npz')){$sources[$rel]=Sha $rel}
$report=[ordered]@{status='PASS_FILE_BINDINGS_AND_BOUND_PRIOR_EVIDENCE';scope='read-only asset/history audit; no model forward, optimization, MC, training or GPU';new_run=(Abs 'output/a_ttq_asset_audit_20260925_01');data=$null;models=$models;history_four_uids=$wp.uids;history_three_arms=$hist;independent_MC_baseline_catalog=$catalog;balanced11_supplement=[ordered]@{model_binding=$models.balanced_11;existing_raw_success_rows=$b11rows.Count;expected_raw_slots=16;errors=$b11errors;failed_UIDs=@($b11errors|ForEach-Object {$_.uid});not_a_seed_selection=$true};semantics=[ordered]@{surface='same frozen2050-node4096-face radial mainfield surface, not original raw asset GT';prior_exact_array_evidence=(Abs $semPath);prior_evidence_sha256=$semSha;all16_file_hashes_equal_prior_checked_assets=$true;new_reconstruction_or_geometry_metric=$false};not_measured=[ordered]@{new_full16_TTQ_run=$true;new_network_forward_or_tensor_rehash=$true;new_optimizer_calls=$true;new_MC=$true;dense_independent_MC_for_unsaved_iterations=$true;remaining12_Warm_TTQ_optimization_trajectories=$true;fresh_isolated_timing=$true};limitations=@('WSL Python launch failed with HCS/0x800705aa in this audit; use native Windows byte/file checks and hash-bound prior exact-array/model evidence. No service restart or process interruption.','Old warm data contain per-iteration internal-loss/angle/timing trace but only saved meshes/independent MC at0,1,4,16 plus raw and chosen optimizer final. Do not interpolate this as measured every-step TTQ.','Old timing is historical nonisolated timing with declared online components. TTQ cost must specify model load, floor setup, initial inference, optimizer and terminal audit; MC timing is separate.','All16 are already-seen development objects; train12/check4 does not create a fresh confirmation set.');source_sha256=$sources;all_original_read_files_sha256=$visited}
$report.data=$data
foreach($kv in @($visited.GetEnumerator())){Must (((Get-FileHash -LiteralPath $kv.Key -Algorithm SHA256).Hash.ToLowerInvariant())-eq$kv.Value) 'Original file changed during audit'}
$report.original_read_assets_unchanged=$true
$report.audit_script_sha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant()
$dest=Join-Path $out 'AUDIT.json';Must (-not(Test-Path $dest)) 'Do not overwrite audit';[IO.File]::WriteAllText($dest,($report|ConvertTo-Json -Depth 40),[Text.UTF8Encoding]::new($false))
Write-Output ('AUDIT_PASS data16 history'+$hist.Count+' baseline_catalog'+$catalog.Count+' failed_balanced11='+$b11errors.Count)
